    if method == "GET":
        return _handle_provenance_get(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def _handle_policies_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    # Validate the whole body before touching any store, so a bad request
    # can never leave a partial policy.
    try:
        build_policy_fields(payload)
    except PolicyValidationError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            exc.message,
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    try:
        record, created = policy_store.add(raw_id, payload)
    except PolicyError as exc:
        return _error(
            start_response, "409 Conflict", exc.code, exc.message
        )

    return _json_response(
        start_response,
        "201 Created" if created else "200 OK",
        record.to_dict(raw_id),
        trailing_newline=True,
    )


def _handle_policies_get(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    record = policy_store.get(raw_id)
    if record is None:
        return _error(
            start_response,
            "404 Not Found",
            "policy_not_found",
            "No policy is registered for this resource.",
        )

    return _json_response(
        start_response,
        "200 OK",
        record.to_dict(raw_id),
        trailing_newline=True,
    )


def _handle_policies(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method == "POST":
        return _handle_policies_post(environ, raw_id, start_response)
    if method == "GET":
        return _handle_policies_get(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def _admission_body_error(environ: dict[str, Any]) -> str | None:
    """Reject an admission request that declares or carries a body."""

    raw_length = environ.get("CONTENT_LENGTH")
    if raw_length is None:
        return None
    if (
        not isinstance(raw_length, str)
        or _NON_NEGATIVE_INT_PATTERN.fullmatch(raw_length) is None
        or int(raw_length) > 0
    ):
        return "This endpoint does not accept a request body."
    return None


def _handle_admission(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "POST":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="POST",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    body_error = _admission_body_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    policy = policy_store.get(raw_id)
    if policy is None:
        return _error(
            start_response,
            "404 Not Found",
            "policy_not_found",
            "No policy is registered for this resource.",
        )

    license_record = sbom_store.get_license(raw_id)
    allowed, reasons = evaluate_policy(
        policy,
        lifecycle_state=lifecycle_store.get(raw_id).state,
        has_sbom=sbom_store.get_sbom(raw_id) is not None,
        has_license=license_record is not None,
        has_provenance=provenance_store.get(raw_id) is not None,
        license_spdx_id=(
            license_record.spdx_id if license_record is not None else None
        ),
        severities=[
            alert.severity for alert in vulnerability_store.list_for(raw_id)
        ],
    )

    return _json_response(
        start_response,
        "200 OK",
        {"id": raw_id, "allowed": allowed, "reasons": reasons},
        trailing_newline=True,
    )


def application(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    try:
        method = str(environ.get("REQUEST_METHOD", "GET")).upper()
        path = str(environ.get("PATH_INFO", "/"))

        if method == "GET" and path == "/health":
            # Kept byte-for-byte compatible with the documented baseline.
            return _json_response(start_response, "200 OK", {"status": "ok"})

        if path == "/resources":
            if method == "GET":
                return _handle_resources_get(environ, start_response)
            if method == "POST":
                return _handle_resources_post(environ, start_response)
            return _error(
                start_response,
                "405 Method Not Allowed",
                "method_not_allowed",
                f"Method {method} is not allowed for this path.",
                allowed="GET, POST",
            )

        if path.startswith("/resources/"):
            suffix = path[len("/resources/"):]
            head, separator, tail = suffix.partition("/")
            if separator and tail == "dependencies":
                return _handle_dependencies(
                    method, environ, head, start_response
                )
            if separator and tail == "impact":
                return _handle_impact(
                    method, environ, head, start_response
                )
            if separator and tail == "verify":
                return _handle_verify(
                    method, environ, head, start_response
                )
            if separator and tail == "assemble":
                return _handle_assemble(
                    method, environ, head, start_response
                )
            if separator and tail == "content":
                return _handle_content(
                    method, environ, head, start_response
                )
            if separator and tail == "lifecycle":
                return _handle_lifecycle(
                    method, environ, head, start_response
                )
            if separator and tail == "vulnerabilities":
                return _handle_vulnerabilities(
                    method, environ, head, start_response
                )
            if separator and tail == "sbom":
                return _handle_sbom(
                    method, environ, head, start_response
                )
            if separator and tail == "license":
                return _handle_license(
                    method, environ, head, start_response
                )
            if separator and tail == "provenance":
                return _handle_provenance(
                    method, environ, head, start_response
                )
            if separator and tail == "policies":
                return _handle_policies(
                    method, environ, head, start_response
                )
            if separator and tail == "admission":
                return _handle_admission(
                    method, environ, head, start_response
                )
            if separator and tail == "chunks/status":
                return _handle_chunks_status(
                    method, environ, head, start_response
                )
            if separator and tail.startswith("chunks/"):
                return _handle_chunk(
                    method, environ, head, tail[len("chunks/"):],
                    start_response,
                )
            if separator and tail == "chunks":
                # The collection itself cannot be addressed: a chunk index is
                # required, so POST is a bad request and other methods 405.
                return _handle_chunk(
                    method, environ, head, "", start_response
                )
            if separator and suffix.endswith("/verify"):
                # The id segment itself contained a path separator; let the
                # verify handler reject it without reading business data.
                return _handle_verify(
                    method, environ, suffix[: -len("/verify")], start_response
                )
            if separator and suffix.endswith("/chunks/status"):
                # Fallback for a separator inside the id segment so the
                # status handler rejects it without creating any state.
                return _handle_chunks_status(
                    method,
                    environ,
                    suffix[: -len("/chunks/status")],
                    start_response,
                )
            if separator and "/chunks/" in suffix:
                # Same fallback for chunk paths with a separator in the id.
                malformed_id, _, raw_index = suffix.rpartition("/chunks/")
                return _handle_chunk(
                    method, environ, malformed_id, raw_index, start_response
                )
            if separator and suffix.endswith("/assemble"):
                return _handle_assemble(
                    method, environ, suffix[: -len("/assemble")], start_response
                )
            if separator and suffix.endswith("/content"):
                return _handle_content(
                    method, environ, suffix[: -len("/content")], start_response
                )
            if separator and suffix.endswith("/lifecycle"):
                return _handle_lifecycle(
                    method,
                    environ,
                    suffix[: -len("/lifecycle")],
                    start_response,
                )
            if separator and suffix.endswith("/vulnerabilities"):
                # Fallback for a separator inside the id segment so the
                # handler rejects it without recording any alert.
                return _handle_vulnerabilities(
                    method,
                    environ,
                    suffix[: -len("/vulnerabilities")],
                    start_response,
                )
            if separator and suffix.endswith("/sbom"):
                # Fallback for a separator inside the id segment so the
                # handler rejects it without recording any document.
                return _handle_sbom(
                    method,
                    environ,
                    suffix[: -len("/sbom")],
                    start_response,
                )
            if separator and suffix.endswith("/license"):
                # Fallback for a separator inside the id segment so the
                # handler rejects it without recording any license.
                return _handle_license(
                    method,
                    environ,
                    suffix[: -len("/license")],
                    start_response,
                )
            if separator and suffix.endswith("/provenance"):
                # Fallback for a separator inside the id segment so the
                # handler rejects it without recording any provenance.
                return _handle_provenance(
                    method,
                    environ,
                    suffix[: -len("/provenance")],
                    start_response,
                )
            if separator and suffix.endswith("/policies"):
                # Fallback for a separator inside the id segment so the
                # handler rejects it without recording any policy.
                return _handle_policies(
                    method,
                    environ,
                    suffix[: -len("/policies")],
                    start_response,
                )
            if separator and suffix.endswith("/admission"):
                # Same fallback so a separator in the id is rejected
                # without performing an evaluation.
                return _handle_admission(
                    method,
                    environ,
                    suffix[: -len("/admission")],
                    start_response,
                )
            # Any other suffix keeps the baseline item semantics (embedded
            # separators are rejected by the item handler).
            return _handle_resource_item(
                method, suffix, start_response
            )

        # Unknown paths and undeclared methods on /health stay as before.
        return _json_response(
            start_response,
            "404 Not Found",
            {"error": "not_found", "message": "The requested resource does not exist."},
        )
    except Exception:  # pragma: no cover - defensive boundary
        # Clients must only ever see agreed statuses, never a stack trace.
        return _error(
            start_response,
            "500 Internal Server Error",
            "internal_error",
            "An unexpected error occurred.",
        )

"""In-process security vulnerability registration for registered resources.

A vulnerability record pairs an advisory identifier with the affected
component, a severity level, a summary and an optional fixed version.
Records are kept per resource in submission order and are never persisted:
stopping or restarting the service clears every alert, and no files are
written. Batching, updates, deletion and concurrency are intentionally out
of scope.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass

#: The four allowed severity levels; input is case-insensitive but the level
#: is always stored and rendered in lowercase.
SEVERITIES: tuple[str, ...] = ("critical", "high", "medium", "low")
SEVERITY_VALUES = frozenset(SEVERITIES)

#: Length caps, counted in Unicode code points.
MAX_ADVISORY_LENGTH = 256
MAX_COMPONENT_LENGTH = 256
MAX_SUMMARY_LENGTH = 2048
MAX_FIXED_VERSION_LENGTH = 256

#: Fields accepted by the registration request; anything else is rejected.
_ALLOWED_FIELDS = frozenset(
    {"advisory", "component", "severity", "summary", "fixed_version"}
)
_REQUIRED_FIELDS = ("advisory", "component", "severity", "summary")


class VulnerabilityValidationError(ValueError):
    """A registration payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class VulnerabilityError(ValueError):
    """A vulnerability operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class Vulnerability:
    """A single vulnerability alert recorded against a resource."""

    id: str
    advisory: str
    component: str
    severity: str
    summary: str
    fixed_version: str | None

    def to_dict(self) -> dict[str, object]:
        return {
            "id": self.id,
            "advisory": self.advisory,
            "component": self.component,
            "severity": self.severity,
            "summary": self.summary,
            "fixed_version": self.fixed_version,
        }


def _required_string(value: object, field: str, limit: int) -> str:
    """Validate a required non-empty string bounded by ``limit`` code points."""

    label = field.capitalize()
    if not isinstance(value, str):
        raise VulnerabilityValidationError(f"Field {field!r} must be a string.")
    if not value:
        raise VulnerabilityValidationError(
            f"Field {field!r} must not be empty."
        )
    if len(value) > limit:
        raise VulnerabilityValidationError(
            f"{label} must not exceed {limit} Unicode code points."
        )
    return value


def build_vulnerability_fields(
    payload: object,
) -> tuple[str, str, str, str, str | None]:
    """Validate a decoded JSON payload and return normalized field values.

    Returns ``(advisory, component, severity, summary, fixed_version)``.
    Severity is matched case-insensitively and normalized to lowercase.
    ``fixed_version`` is ``None`` when omitted.
    """

    if not isinstance(payload, dict):
        raise VulnerabilityValidationError(
            "Request body must be a JSON object."
        )

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise VulnerabilityValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise VulnerabilityValidationError(
                f"Missing required field: {field!r}."
            )

    advisory = _required_string(
        payload["advisory"], "advisory", MAX_ADVISORY_LENGTH
    )
    component = _required_string(
        payload["component"], "component", MAX_COMPONENT_LENGTH
    )

    severity_raw = payload["severity"]
    if not isinstance(severity_raw, str) or not severity_raw:
        raise VulnerabilityValidationError(
            "Field 'severity' must be one of: critical, high, medium, low "
            "(case-insensitive)."
        )
    severity = severity_raw.lower()
    if severity not in SEVERITY_VALUES:
        raise VulnerabilityValidationError(
            "Field 'severity' must be one of: critical, high, medium, low "
            "(case-insensitive)."
        )

    summary = _required_string(
        payload["summary"], "summary", MAX_SUMMARY_LENGTH
    )

    fixed_version: str | None = None
    if "fixed_version" in payload:
        value = payload["fixed_version"]
        if not isinstance(value, str):
            raise VulnerabilityValidationError(
                "Field 'fixed_version' must be a string."
            )
        if not value:
            raise VulnerabilityValidationError(
                "Field 'fixed_version' must not be empty."
            )
        if len(value) > MAX_FIXED_VERSION_LENGTH:
            raise VulnerabilityValidationError(
                f"Fixed version must not exceed {MAX_FIXED_VERSION_LENGTH} "
                "Unicode code points."
            )
        fixed_version = value

    return advisory, component, severity, summary, fixed_version


class VulnerabilityStore:
    """Process-local, submission-ordered vulnerability storage per resource."""

    def __init__(self) -> None:
        # resource id -> alerts in submission order.
        self._records: dict[str, list[Vulnerability]] = {}
        # resource id -> (advisory, component) duplicates already seen.
        self._keys: dict[str, set[tuple[str, str]]] = {}

    def reset(self) -> None:
        self._records = {}
        self._keys = {}

    def add(self, resource_id: str, payload: object) -> Vulnerability:
        """Validate and append a vulnerability alert for ``resource_id``.

        Raises :class:`VulnerabilityValidationError` for an invalid payload
        or :class:`VulnerabilityError` with code ``duplicate_vulnerability``
        when the same advisory identifier and component pair is already
        recorded for the resource; the original alert is left untouched.
        """

        advisory, component, severity, summary, fixed_version = (
            build_vulnerability_fields(payload)
        )
        key = (advisory, component)
        resource_keys = self._keys.setdefault(resource_id, set())
        if key in resource_keys:
            raise VulnerabilityError(
                "duplicate_vulnerability",
                "An alert with the same advisory and component already "
                "exists for this resource.",
            )

        record = Vulnerability(
            id=uuid.uuid4().hex,
            advisory=advisory,
            component=component,
            severity=severity,
            summary=summary,
            fixed_version=fixed_version,
        )
        self._records.setdefault(resource_id, []).append(record)
        resource_keys.add(key)
        return record

    def list_for(
        self, resource_id: str, severity: str | None = None
    ) -> list[Vulnerability]:
        """Return a resource's alerts in submission order.

        With ``severity`` set (already normalized to lowercase), only alerts
        at that level are returned; the relative submission order is kept.
        """

        records = self._records.get(resource_id, ())
        if severity is None:
            return list(records)
        return [record for record in records if record.severity == severity]

"""In-process admission policies for registered resources.

Each resource keeps at most one policy. A policy names a non-empty
display name, the evidence it requires (``sbom``, ``license`` and/or
``provenance``), an allowlist of accepted SPDX license identifiers
(which may be empty) and the maximum accepted vulnerability severity.
Nothing here is persisted: stopping or restarting the service clears
every policy and every admission result; no files are written.

Admission is a single read-only decision per resource. A resource in a
withdrawn or quarantined lifecycle state is denied with
``state_blocked`` before anything else is checked. Missing required
evidence contributes ``no_sbom``, ``no_license`` or ``no_provenance``.
A non-empty allowlist that does not contain the resource's declared
SPDX identifier contributes ``license_denied``. Any recorded alert
above the policy's severity ceiling contributes ``severity_exceeded``.
When several groups fire, their codes are ordered as state, evidence,
license and then severity.
"""

from __future__ import annotations

from dataclasses import dataclass

#: The fixed set of evidence a policy may require; order also fixes the
#: stable order in which missing-evidence reason codes are reported.
EVIDENCE: tuple[str, ...] = ("sbom", "license", "provenance")
EVIDENCE_VALUES = frozenset(EVIDENCE)

#: The four public severity levels, from most to least severe. Severity
#: comparison is case-insensitive; the value is stored in lowercase.
SEVERITIES: tuple[str, ...] = ("critical", "high", "medium", "low")
SEVERITY_VALUES = frozenset(SEVERITIES)
_SEVERITY_RANK = {severity: index for index, severity in enumerate(SEVERITIES)}

#: A policy name is non-empty and bounded by 256 Unicode code points.
MAX_NAME_LENGTH = 256

#: Fields accepted by the registration request; all four are required.
_ALLOWED_FIELDS = frozenset(
    {"name", "evidence_requirements", "license_allowlist", "max_severity"}
)
_REQUIRED_FIELDS = (
    "name",
    "evidence_requirements",
    "license_allowlist",
    "max_severity",
)

#: Evidence requirement key -> reason code reported when it is missing.
_EVIDENCE_REASON = {
    "provenance": "no_provenance",
    "sbom": "no_sbom",
    "license": "no_license",
}


class PolicyValidationError(ValueError):
    """A policy payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class PolicyError(ValueError):
    """A policy operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class PolicyRecord:
    """The single admission policy stored for a resource."""

    name: str
    evidence_requirements: tuple[str, ...]
    license_allowlist: tuple[str, ...]
    max_severity: str

    def to_dict(self, resource_id: str) -> dict[str, object]:
        return {
            "id": resource_id,
            "name": self.name,
            "evidence_requirements": list(self.evidence_requirements),
            "license_allowlist": list(self.license_allowlist),
            "max_severity": self.max_severity,
        }


def build_policy_fields(
    payload: object,
) -> tuple[str, tuple[str, ...], tuple[str, ...], str]:
    """Validate a decoded policy payload and return normalized values.

    Returns ``(name, evidence_requirements, license_allowlist,
    max_severity)``. Evidence and SPDX identifiers keep their submission
    order and must not repeat; the allowlist may be empty. The severity
    ceiling is normalized to lowercase.
    """

    if not isinstance(payload, dict):
        raise PolicyValidationError("Request body must be a JSON object.")

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise PolicyValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise PolicyValidationError(
                f"Missing required field: {field!r}."
            )

    name = payload["name"]
    if not isinstance(name, str):
        raise PolicyValidationError("Field 'name' must be a string.")
    if not name:
        raise PolicyValidationError("Field 'name' must not be empty.")
    if len(name) > MAX_NAME_LENGTH:
        raise PolicyValidationError(
            f"Field 'name' must not exceed {MAX_NAME_LENGTH} Unicode code points."
        )

    raw_evidence = payload["evidence_requirements"]
    if not isinstance(raw_evidence, list):
        raise PolicyValidationError(
            "Field 'evidence_requirements' must be an array."
        )
    evidence: list[str] = []
    seen_evidence: set[str] = set()
    for item in raw_evidence:
        if not isinstance(item, str) or item not in EVIDENCE_VALUES:
            raise PolicyValidationError(
                "Field 'evidence_requirements' must only contain: "
                "provenance, sbom, license."
            )
        if item in seen_evidence:
            raise PolicyValidationError(
                "Field 'evidence_requirements' must not repeat a value."
            )
        seen_evidence.add(item)
        evidence.append(item)

    raw_allowlist = payload["license_allowlist"]
    if not isinstance(raw_allowlist, list):
        raise PolicyValidationError(
            "Field 'license_allowlist' must be an array."
        )
    allowlist: list[str] = []
    seen_license: set[str] = set()
    for item in raw_allowlist:
        if not isinstance(item, str) or not item:
            raise PolicyValidationError(
                "Field 'license_allowlist' must only contain non-empty "
                "SPDX identifier strings."
            )
        if item in seen_license:
            raise PolicyValidationError(
                "Field 'license_allowlist' must not repeat a value."
            )
        seen_license.add(item)
        allowlist.append(item)

    raw_severity = payload["max_severity"]
    if not isinstance(raw_severity, str) or not raw_severity:
        raise PolicyValidationError(
            "Field 'max_severity' must be one of: critical, high, medium, low."
        )
    max_severity = raw_severity.lower()
    if max_severity not in SEVERITY_VALUES:
        raise PolicyValidationError(
            "Field 'max_severity' must be one of: critical, high, medium, low."
        )

    return name, tuple(evidence), tuple(allowlist), max_severity


class PolicyStore:
    """Process-local storage of at most one admission policy per resource."""

    def __init__(self) -> None:
        self._records: dict[str, PolicyRecord] = {}

    def reset(self) -> None:
        self._records = {}

    def add(
        self, resource_id: str, payload: object
    ) -> tuple[PolicyRecord, bool]:
        """Validate and record the policy for ``resource_id``.

        Returns ``(record, created)`` where ``created`` is ``True`` for a
        first registration (HTTP 201) and ``False`` for an idempotent
        resubmission of the exact same content (HTTP 200). A different
        policy raises :class:`PolicyError` with code ``policy_conflict``
        and the stored record is never overwritten.
        """

        name, evidence, allowlist, max_severity = build_policy_fields(payload)
        record = PolicyRecord(
            name=name,
            evidence_requirements=evidence,
            license_allowlist=allowlist,
            max_severity=max_severity,
        )

        existing = self._records.get(resource_id)
        if existing is not None:
            if existing == record:
                return existing, False
            raise PolicyError(
                "policy_conflict",
                "A different policy is already registered for this resource.",
            )

        self._records[resource_id] = record
        return record, True

    def get(self, resource_id: str) -> PolicyRecord | None:
        return self._records.get(resource_id)


def evaluate_policy(
    policy: PolicyRecord,
    *,
    lifecycle_state: str,
    has_sbom: bool,
    has_license: bool,
    has_provenance: bool,
    license_spdx_id: str | None,
    severities: "list[str]",
) -> tuple[bool, list[str]]:
    """Run the read-only admission decision for one resource.

    Returns ``(allowed, reasons)``. A blocked lifecycle state short-
    circuits every other check. Otherwise missing evidence, a denied
    license and excessive severity are collected together and ordered
    as state, evidence (sbom, license, provenance), license, severity.

    ``severities`` are the stored lowercase severity levels of every
    alert recorded against the resource; comparison against the ceiling
    is case-insensitive.
    """

    if lifecycle_state in ("withdrawn", "quarantined"):
        return False, ["state_blocked"]

    reasons: list[str] = []

    present = {
        "provenance": has_provenance,
        "sbom": has_sbom,
        "license": has_license,
    }
    for item in EVIDENCE:
        if item in policy.evidence_requirements and not present[item]:
            reasons.append(_EVIDENCE_REASON[item])

    if policy.license_allowlist and license_spdx_id not in policy.license_allowlist:
        reasons.append("license_denied")

    ceiling = _SEVERITY_RANK[policy.max_severity]
    for severity in severities:
        if _SEVERITY_RANK[severity.lower()] < ceiling:
            reasons.append("severity_exceeded")
            break

    return not reasons, reasons

"""In-process lifecycle states for registered resources.

Every resource starts in ``staged`` and can be promoted to ``released``
once its content is assembled and its dependencies are healthy, or be
withdrawn or quarantined with a recorded reason. Only the current state
and reason are kept, in the current process memory only: nothing is
persisted and a restart resets every resource to ``staged``.
"""

from __future__ import annotations

from dataclasses import dataclass

#: The fixed set of lifecycle states; names are case-sensitive.
STATES: tuple[str, ...] = ("staged", "released", "withdrawn", "quarantined")
STATE_VALUES = frozenset(STATES)

#: Target states that always require a non-empty reason.
REASON_REQUIRED_STATES = frozenset({"withdrawn", "quarantined"})

#: Maximum reason length, counted in Unicode code points.
MAX_REASON_LENGTH = 1024

#: Permitted state transitions. ``("staged", "released")`` is additionally
#: gated on assembled content and healthy dependencies by the caller.
_ALLOWED_TRANSITIONS = frozenset(
    {
        ("staged", "released"),
        ("staged", "quarantined"),
        ("released", "withdrawn"),
        ("released", "quarantined"),
        ("withdrawn", "staged"),
        ("quarantined", "staged"),
    }
)

#: States that block a dependent resource from being released.
BLOCKING_STATES = frozenset({"withdrawn", "quarantined"})


class LifecycleError(ValueError):
    """A lifecycle transition could not be applied.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class LifecycleRecord:
    """The current lifecycle state of one resource."""

    state: str
    reason: str | None


class LifecycleStore:
    """Process-local current lifecycle state per resource id."""

    def __init__(self) -> None:
        self._records: dict[str, LifecycleRecord] = {}

    def reset(self) -> None:
        self._records = {}

    def get(self, resource_id: str) -> LifecycleRecord:
        """Return the current record; resources default to ``staged``."""

        return self._records.get(
            resource_id, LifecycleRecord(state="staged", reason=None)
        )

    def set(self, resource_id: str, record: LifecycleRecord) -> None:
        self._records[resource_id] = record

    def apply(
        self, current: LifecycleRecord, target: str, reason: str | None
    ) -> LifecycleRecord:
        """Compute the record for a requested transition.

        Resubmitting the current state with the current reason is an
        idempotent no-op and returns the record unchanged. Any other
        same-state request (a reason change) and any transition outside
        the permitted set raises :class:`LifecycleError` with code
        ``invalid_state_transition``; the caller leaves state untouched.
        """

        if target == current.state:
            if reason == current.reason:
                return current
            raise LifecycleError(
                "invalid_state_transition",
                "The recorded reason must not be changed.",
            )
        if (current.state, target) not in _ALLOWED_TRANSITIONS:
            raise LifecycleError(
                "invalid_state_transition",
                f"Transition from {current.state!r} to {target!r} is not "
                "allowed.",
            )
        return LifecycleRecord(state=target, reason=reason)

"""In-process SBOM documents and license declarations for resources.

Each resource keeps at most one SBOM document and at most one license
declaration. SBOM components are preserved in submission order together
with their name, version and lowercase 64-character hexadecimal digest.
Nothing here is persisted: stopping or restarting the service clears
every document and license, and no files are written.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

#: The two accepted SBOM document formats; input is case-sensitive.
FORMATS: tuple[str, ...] = ("spdx", "cyclonedx")
FORMAT_VALUES = frozenset(FORMATS)

#: A component digest is exactly 64 hexadecimal characters; mixed case is
#: accepted but the digest is always stored and rendered in lowercase.
_DIGEST_PATTERN = re.compile(r"[0-9a-fA-F]{64}")

#: Fields accepted by the SBOM registration request; anything else is
#: rejected. Both fields are required (``components`` may be an empty list).
_SBOM_ALLOWED_FIELDS = frozenset({"format", "components"})

#: Fields accepted by the license registration request; ``source`` is
#: optional and is rendered as ``null`` when omitted.
_LICENSE_ALLOWED_FIELDS = frozenset({"spdx_id", "source"})


class SbomValidationError(ValueError):
    """An SBOM or license payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class SbomError(ValueError):
    """An SBOM or license operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class SbomComponent:
    """A single SBOM component identified by name, version and digest."""

    name: str
    version: str
    digest: str

    def to_dict(self) -> dict[str, object]:
        return {"name": self.name, "version": self.version, "digest": self.digest}


@dataclass(frozen=True, slots=True)
class SbomDocument:
    """The single SBOM document recorded against a resource."""

    format: str
    components: tuple[SbomComponent, ...]

    def to_dict(self, resource_id: str) -> dict[str, object]:
        return {
            "id": resource_id,
            "format": self.format,
            "components": [component.to_dict() for component in self.components],
        }


@dataclass(frozen=True, slots=True)
class LicenseRecord:
    """The single license declaration recorded against a resource."""

    spdx_id: str
    source: str | None

    def to_dict(self, resource_id: str) -> dict[str, object]:
        return {"id": resource_id, "spdx_id": self.spdx_id, "source": self.source}


def _require_non_empty_string(value: object, label: str) -> str:
    if not isinstance(value, str):
        raise SbomValidationError(f"{label} must be a string.")
    if not value:
        raise SbomValidationError(f"{label} must not be empty.")
    return value


def build_sbom_fields(payload: object) -> tuple[str, tuple[SbomComponent, ...]]:
    """Validate a decoded SBOM payload and return normalized values.

    Returns ``(format, components)``. ``format`` must be ``spdx`` or
    ``cyclonedx`` (case-sensitive); ``components`` must be a list (possibly
    empty) of objects whose ``name``, ``version`` and ``digest`` are
    non-empty strings, with ``digest`` normalized to lowercase. Components
    are returned in their submitted order.
    """

    if not isinstance(payload, dict):
        raise SbomValidationError("Request body must be a JSON object.")

    unknown_fields = set(payload) - _SBOM_ALLOWED_FIELDS
    if unknown_fields:
        raise SbomValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    if "format" not in payload:
        raise SbomValidationError("Missing required field: 'format'.")
    format_value = payload["format"]
    if not isinstance(format_value, str) or format_value not in FORMAT_VALUES:
        raise SbomValidationError(
            "Field 'format' must be one of: spdx, cyclonedx."
        )

    if "components" not in payload:
        raise SbomValidationError("Missing required field: 'components'.")
    raw_components = payload["components"]
    if not isinstance(raw_components, list):
        raise SbomValidationError("Field 'components' must be an array.")

    components: list[SbomComponent] = []
    for position, raw_component in enumerate(raw_components):
        if not isinstance(raw_component, dict):
            raise SbomValidationError(
                f"Component at index {position} must be a JSON object."
            )
        component_unknown = set(raw_component) - {"name", "version", "digest"}
        if component_unknown:
            raise SbomValidationError(
                f"Unknown field: {sorted(component_unknown)[0]!r}."
            )
        for field in ("name", "version", "digest"):
            if field not in raw_component:
                raise SbomValidationError(
                    f"Component at index {position} is missing required "
                    f"field: {field!r}."
                )
        name = _require_non_empty_string(
            raw_component["name"], "Component field 'name'"
        )
        version = _require_non_empty_string(
            raw_component["version"], "Component field 'version'"
        )
        raw_digest = raw_component["digest"]
        if (
            not isinstance(raw_digest, str)
            or _DIGEST_PATTERN.fullmatch(raw_digest) is None
        ):
            raise SbomValidationError(
                "Component field 'digest' must be a 64-character "
                "hexadecimal string."
            )
        components.append(
            SbomComponent(name=name, version=version, digest=raw_digest.lower())
        )

    return format_value, tuple(components)


def build_license_fields(payload: object) -> tuple[str, str | None]:
    """Validate a decoded license payload and return ``(spdx_id, source)``."""

    if not isinstance(payload, dict):
        raise SbomValidationError("Request body must be a JSON object.")

    unknown_fields = set(payload) - _LICENSE_ALLOWED_FIELDS
    if unknown_fields:
        raise SbomValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    if "spdx_id" not in payload:
        raise SbomValidationError("Missing required field: 'spdx_id'.")
    spdx_id = _require_non_empty_string(payload["spdx_id"], "Field 'spdx_id'")

    source: str | None = None
    if "source" in payload:
        source = _require_non_empty_string(payload["source"], "Field 'source'")

    return spdx_id, source


class SbomStore:
    """Process-local storage of at most one SBOM and license per resource."""

    def __init__(self) -> None:
        self._sboms: dict[str, SbomDocument] = {}
        self._licenses: dict[str, LicenseRecord] = {}

    def reset(self) -> None:
        self._sboms = {}
        self._licenses = {}

    # --- SBOM --------------------------------------------------------------

    def add_sbom(
        self, resource_id: str, payload: object
    ) -> tuple[SbomDocument, bool]:
        """Validate and record the SBOM document for ``resource_id``.

        Returns ``(document, created)`` where ``created`` is ``True`` for a
        first registration (HTTP 201) and ``False`` for an idempotent repeat
        of the exact same document (HTTP 200).

        Raises :class:`SbomValidationError` for an invalid payload,
        :class:`SbomError` with code ``duplicate_component`` when the
        submitted components repeat a name/version/digest triple, or
        ``sbom_conflict`` when a different document is already recorded;
        the stored document is never modified.
        """

        format_value, components = build_sbom_fields(payload)

        seen: set[tuple[str, str, str]] = set()
        for component in components:
            triple = (component.name, component.version, component.digest)
            if triple in seen:
                raise SbomError(
                    "duplicate_component",
                    "An identical component (same name, version and "
                    "digest) is listed more than once.",
                )
            seen.add(triple)

        document = SbomDocument(format=format_value, components=components)

        existing = self._sboms.get(resource_id)
        if existing is not None:
            if existing == document:
                return existing, False
            raise SbomError(
                "sbom_conflict",
                "A different SBOM document is already recorded for this "
                "resource.",
            )

        self._sboms[resource_id] = document
        return document, True

    def get_sbom(self, resource_id: str) -> SbomDocument | None:
        return self._sboms.get(resource_id)

    # --- License -----------------------------------------------------------

    def add_license(
        self, resource_id: str, payload: object
    ) -> tuple[LicenseRecord, bool]:
        """Validate and record the license declaration for ``resource_id``.

        Returns ``(record, created)`` with ``created`` ``False`` for an
        idempotent repeat of the same declaration (HTTP 200). A different
        declaration raises :class:`SbomError` with code
        ``license_conflict``; the stored declaration is left untouched.
        """

        spdx_id, source = build_license_fields(payload)
        record = LicenseRecord(spdx_id=spdx_id, source=source)

        existing = self._licenses.get(resource_id)
        if existing is not None:
            if existing == record:
                return existing, False
            raise SbomError(
                "license_conflict",
                "A different license is already declared for this resource.",
            )

        self._licenses[resource_id] = record
        return record, True

    def get_license(self, resource_id: str) -> LicenseRecord | None:
        return self._licenses.get(resource_id)

from __future__ import annotations

import hashlib
import io
import json
import unittest

from provenance_api.app import application, reset_state

DIGEST_A = "a" * 64
DIGEST_B = "b" * 64
EMPTY_DIGEST = hashlib.sha256(b"").hexdigest()


def call(
    method: str,
    path: str,
    body: bytes | str | dict[str, object] | None = None,
    *,
    query_string: str | None = None,
    content_type: str | None = "application/json",
    omit_content_length: bool = False,
    content_length: int | str | None = None,
) -> tuple[str, list[tuple[str, str]], bytes]:
    if body is None:
        payload = b""
    elif isinstance(body, dict):
        payload = json.dumps(body).encode("utf-8")
    else:
        payload = body.encode("utf-8") if isinstance(body, str) else body

    environ: dict[str, object] = {
        "REQUEST_METHOD": method,
        "PATH_INFO": path,
        "QUERY_STRING": query_string if query_string is not None else "",
        "wsgi.input": io.BytesIO(payload),
    }
    if not omit_content_length:
        environ["CONTENT_LENGTH"] = (
            str(len(payload)) if content_length is None else str(content_length)
        )
    if content_type is not None:
        environ["CONTENT_TYPE"] = content_type
    captured: dict[str, object] = {}

    def start_response(status: str, headers: list[tuple[str, str]]) -> None:
        captured["status"] = status
        captured["headers"] = headers

    chunks = application(environ, start_response)
    return str(captured["status"]), list(captured["headers"]), b"".join(chunks)


def call_json(
    method: str,
    path: str,
    body: bytes | str | dict[str, object] | None = None,
    *,
    query_string: str | None = None,
) -> tuple[str, list[tuple[str, str]], dict[str, object]]:
    status, headers, raw = call(method, path, body, query_string=query_string)
    return status, headers, json.loads(raw.decode("utf-8"))


def policy_payload(**overrides: object) -> dict[str, object]:
    payload: dict[str, object] = {
        "name": "release-gate",
        "evidence_requirements": ["sbom", "license", "provenance"],
        "license_allowlist": ["Apache-2.0", "MIT"],
        "max_severity": "high",
    }
    payload.update(overrides)
    return payload


class PolicyTests(unittest.TestCase):
    def setUp(self) -> None:
        reset_state()
        self.resource_id = self._create(DIGEST_A)

    def _create(self, digest: str = DIGEST_A, name: str = "r") -> str:
        _s, _h, body = call_json(
            "POST",
            "/resources",
            {"name": name, "category": "code", "digest": digest},
        )
        return str(body["id"])

    def _register(
        self, resource_id: str | None = None, **overrides: object
    ) -> tuple[str, list[tuple[str, str]], dict[str, object]]:
        return call_json(
            "POST",
            f"/resources/{resource_id or self.resource_id}/policies",
            policy_payload(**overrides),
        )

    # --- Registration ------------------------------------------------------

    def test_register_policy_returns_201_and_echoes(self) -> None:
        status, headers, body = self._register()

        self.assertEqual(status, "201 Created")
        self.assertIn(
            ("Content-Type", "application/json; charset=utf-8"), headers
        )
        self.assertEqual(
            body,
            {
                "id": self.resource_id,
                "name": "release-gate",
                "evidence_requirements": ["sbom", "license", "provenance"],
                "license_allowlist": ["Apache-2.0", "MIT"],
                "max_severity": "high",
            },
        )

    def test_max_severity_is_case_insensitive_and_stored_lowercase(self) -> None:
        _s, _h, body = self._register(max_severity="CRITICAL")
        self.assertEqual(body["max_severity"], "critical")

